import Openai from "openai";

const client = new Openai({
  apiKey: process.env["OPENAI_API_KEY"],
});

const result = await client.vectorStores.search("vs_abc123", { query: "string", rewrite_query: false, max_num_results: 10, filters: { type: "eq", key: "string", value: "string" }, ranking_options: { ranker: "none", score_threshold: 0 } });
console.log(result);
